-- ── story 3-7a: batch recall ────────────────────────────────────────────
-- Generated by drizzle-kit (the two tables and the six indexes) and
-- hand-amended around the generated part: the fail-fast guard, `IF NOT
-- EXISTS` on every table and index (guide §3), the CHECKs, the RLS policies
-- and the post-migration probes (drizzle-kit is blind to CHECKs and RLS;
-- `bun run db:generate` afterwards reports "No schema changes").
--
--   batch_recalls       — one recall document `RCL-nnnnnn` over ONE client's
--                         lots: `mode` live | mock, `status` open | closed,
--                         the brand's reason note (shown to the client) and
--                         reference, who opened it, and — once closed — who,
--                         when, the close note, the frozen `close_summary`
--                         (schema v1) and the batches it released. RLS: the
--                         0041 client shape on its own `client_id`.
--   batch_recall_lines  — one batch of a recall (its SKU and code frozen at
--                         open) and whether THIS recall blocked it. RLS:
--                         tenant only — the portal reaches a line only by
--                         joining its recall (guide §7e).
--
-- Two indexes on populated tables (A8 / A9):
--   orders_tenant_client_open_idx — a client's OPEN orders per warehouse
--     (partial on `ORDER_OPEN_STATUSES`), where the recall's held-order read
--     starts;
--   batches_tenant_code_norm_idx — the normalised lot-code match (letters and
--     digits, upper-cased), the candidates read's `LOT_CODE_NORM_SQL`.
-- On a LARGE table the deploy migrator refuses the build until it is pre-built
-- under the same name and valid (DEPLOY.md §5). The release note carries:
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "orders_tenant_client_open_idx" ON "orders" USING btree ("tenant_id","client_id","warehouse_id") WHERE "status" IN ('accepted','ready_to_dispatch');
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "batches_tenant_code_norm_idx" ON "batches" USING btree ("tenant_id",(upper(regexp_replace("code", '[^A-Za-z0-9]', '', 'g'))));
-- Rollback (outside a transaction):
--   DROP INDEX CONCURRENTLY IF EXISTS "orders_tenant_client_open_idx";
--   DROP INDEX CONCURRENTLY IF EXISTS "batches_tenant_code_norm_idx";
--
-- No data statements, no backfill, no enum: purely additive. The two tables
-- are new and empty, so their CHECKs cost nothing.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'batch_recalls'
	) THEN
		RAISE EXCEPTION 'migration 0101: batch_recalls already exists — this migration has already been applied.';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'webhook_endpoints'
	) THEN
		RAISE EXCEPTION 'migration 0101 is out of order: webhook_endpoints does not exist — 0100 must be applied first.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "batch_recall_lines" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"recall_id" uuid NOT NULL,
	"batch_id" uuid NOT NULL,
	"sku_id" uuid NOT NULL,
	"batch_code" text NOT NULL,
	"blocked_by_recall" boolean NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "batch_recalls" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"code" text NOT NULL,
	"mode" text DEFAULT 'live' NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"reason_note" text NOT NULL,
	"external_ref" text,
	"opened_at" timestamp with time zone NOT NULL,
	"opened_by" uuid NOT NULL,
	"closed_at" timestamp with time zone,
	"closed_by" uuid,
	"close_note" text,
	"close_summary" jsonb,
	"released_batch_ids" uuid[],
	"first_report_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "batch_recall_lines_tenant_recall_batch_unique" ON "batch_recall_lines" USING btree ("tenant_id","recall_id","batch_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "batch_recall_lines_tenant_batch_idx" ON "batch_recall_lines" USING btree ("tenant_id","batch_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "batch_recalls_tenant_code_unique" ON "batch_recalls" USING btree ("tenant_id","code");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "batch_recalls_tenant_created_at_id_idx" ON "batch_recalls" USING btree ("tenant_id","created_at","id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "batch_recalls_tenant_client_created_at_id_idx" ON "batch_recalls" USING btree ("tenant_id","client_id","created_at","id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "batch_recalls_tenant_external_ref_idx" ON "batch_recalls" USING btree ("tenant_id","external_ref");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "batches_tenant_code_norm_idx" ON "batches" USING btree ("tenant_id",(upper(regexp_replace("code", '[^A-Za-z0-9]', '', 'g'))));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "orders_tenant_client_open_idx" ON "orders" USING btree ("tenant_id","client_id","warehouse_id") WHERE "status" IN ('accepted','ready_to_dispatch');--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
-- Text lengths are in characters (code points — `char_length`), the command's
-- `[...s].length`; every note and ref is stored trimmed, so `btrim` only
-- refuses a blank one.
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_code_check" CHECK ("code" ~ '^RCL-[0-9]{6,9}$');--> statement-breakpoint
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_status_check" CHECK ("status" IN ('open','closed'));--> statement-breakpoint
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_mode_check" CHECK ("mode" IN ('live','mock'));--> statement-breakpoint
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_reason_note_check" CHECK (char_length(btrim("reason_note")) BETWEEN 1 AND 500);--> statement-breakpoint
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_external_ref_check" CHECK ("external_ref" IS NULL OR char_length(btrim("external_ref")) BETWEEN 1 AND 100);--> statement-breakpoint
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_close_note_check" CHECK ("close_note" IS NULL OR char_length(btrim("close_note")) BETWEEN 1 AND 500);--> statement-breakpoint
-- A closed recall carries every close fact; an open one carries none of the
-- four, and released batches only once closed.
ALTER TABLE "batch_recalls" ADD CONSTRAINT "batch_recalls_closed_pairing" CHECK (
	(("status" = 'closed') = ("closed_at" IS NOT NULL AND "closed_by" IS NOT NULL AND "close_note" IS NOT NULL AND "close_summary" IS NOT NULL))
	AND ("released_batch_ids" IS NULL OR "status" = 'closed')
);--> statement-breakpoint
-- ── hand-amended: RLS ────────────────────────────────────────────────────
ALTER TABLE "batch_recalls" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "batch_recalls_tenant_isolation" ON "batch_recalls"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
ALTER TABLE "batch_recall_lines" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "batch_recall_lines_tenant_isolation" ON "batch_recall_lines"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0092 model) ────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT — and each violates ONLY its target
-- (CHECKs run in name order, guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	BEGIN
		INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","mode","status","reason_note","external_ref","opened_at","opened_by")
		VALUES
			(gen_random_uuid(), t, c, 'RCL-000001', 'live', 'open', 'Supplier recall: label error', NULL, now(), u),
			(gen_random_uuid(), t, c, 'RCL-123456789', 'mock', 'open', 'Mock drill', 'BRAND-REF-1', now(), u);
		INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","mode","status","reason_note","opened_at","opened_by",
			"closed_at","closed_by","close_note","close_summary","released_batch_ids")
		VALUES (gen_random_uuid(), t, c, 'RCL-000002', 'live', 'closed', 'n', now(), u, now(), u, 'destroyed', '{"v":1}'::jsonb, ARRAY[gen_random_uuid()]),
			(gen_random_uuid(), t, c, 'RCL-000003', 'live', 'closed', 'n', now(), u, now(), u, 'kept blocked', '{"v":1}'::jsonb, NULL);
		INSERT INTO "batch_recall_lines" ("id","tenant_id","recall_id","batch_id","sku_id","batch_code","blocked_by_recall")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 'L-1', true);
		RAISE EXCEPTION USING ERRCODE = 'P0101';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0101: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0101' THEN
			NULL;
	END;
	FOREACH probe IN ARRAY ARRAY[
		'short code', 'lower-case code', 'unknown status', 'unknown mode', 'blank reason note', 'long reason note',
		'blank ref', '101-code-point ref', 'blank close note', 'closed without a summary', 'open with close facts',
		'released while open'
	] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe IN ('short code', 'lower-case code') THEN 'batch_recalls_code_check'
			WHEN probe = 'unknown status' THEN 'batch_recalls_status_check'
			WHEN probe = 'unknown mode' THEN 'batch_recalls_mode_check'
			WHEN probe IN ('blank reason note', 'long reason note') THEN 'batch_recalls_reason_note_check'
			WHEN probe IN ('blank ref', '101-code-point ref') THEN 'batch_recalls_external_ref_check'
			WHEN probe = 'blank close note' THEN 'batch_recalls_close_note_check'
			ELSE 'batch_recalls_closed_pairing' END;
		BEGIN
			CASE probe
				WHEN 'short code' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-12', 'n', now(), u);
				WHEN 'lower-case code' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'rcl-000010', 'n', now(), u);
				WHEN 'unknown status' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","status","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000011', 'paused', 'n', now(), u);
				WHEN 'unknown mode' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","mode","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000012', 'drill', 'n', now(), u);
				WHEN 'blank reason note' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000013', '   ', now(), u);
				WHEN 'long reason note' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000014', repeat('é', 501), now(), u);
				WHEN 'blank ref' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","external_ref","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000015', 'n', '  ', now(), u);
				WHEN '101-code-point ref' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","reason_note","external_ref","opened_at","opened_by")
					VALUES (gen_random_uuid(), t, c, 'RCL-000016', 'n', repeat('ü', 101), now(), u);
				WHEN 'blank close note' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","status","reason_note","opened_at","opened_by","closed_at","closed_by","close_note","close_summary")
					VALUES (gen_random_uuid(), t, c, 'RCL-000017', 'closed', 'n', now(), u, now(), u, ' ', '{"v":1}'::jsonb);
				WHEN 'closed without a summary' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","status","reason_note","opened_at","opened_by","closed_at","closed_by","close_note")
					VALUES (gen_random_uuid(), t, c, 'RCL-000018', 'closed', 'n', now(), u, now(), u, 'done');
				WHEN 'open with close facts' THEN
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","status","reason_note","opened_at","opened_by","closed_at","closed_by","close_note","close_summary")
					VALUES (gen_random_uuid(), t, c, 'RCL-000019', 'open', 'n', now(), u, now(), u, 'done', '{"v":1}'::jsonb);
				ELSE
					INSERT INTO "batch_recalls" ("id","tenant_id","client_id","code","status","reason_note","opened_at","opened_by","released_batch_ids")
					VALUES (gen_random_uuid(), t, c, 'RCL-000020', 'open', 'n', now(), u, ARRAY[gen_random_uuid()]);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0101: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "batch_recalls" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "batch_recall_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0101: a probe row survived.';
	END IF;
	IF EXISTS (
		SELECT 1 FROM pg_class
		 WHERE relname IN ('batch_recalls', 'batch_recall_lines') AND relkind = 'r' AND NOT relrowsecurity
	) OR (SELECT count(*) FROM pg_class WHERE relname IN ('batch_recalls', 'batch_recall_lines') AND relkind = 'r') <> 2 THEN
		RAISE EXCEPTION 'migration 0101: row level security is not enabled on both recall tables.';
	END IF;
	IF (SELECT count(*) FROM pg_policy WHERE polname IN ('batch_recalls_tenant_isolation', 'batch_recall_lines_tenant_isolation')) <> 2 THEN
		RAISE EXCEPTION 'migration 0101: a recall RLS policy is missing.';
	END IF;
END $$;
--> statement-breakpoint
-- ── the two new indexes exist and are valid — outside any DO block (A20) ──
-- `1 / count(*)` divides by zero when the index is missing or invalid.
SELECT 1 / count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE c.relname = 'orders_tenant_client_open_idx' AND i.indisvalid;--> statement-breakpoint
SELECT 1 / count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE c.relname = 'batches_tenant_code_norm_idx' AND i.indisvalid;
